('CA-LBQCH', '07500608CT6C01.kmz', '214aa4e5ca406058b0204d396ce84ad380d03d43454a24ba7f7f058344588cc2', '750 La Boquilla o Lago Toronto, Chih., CIA. AGRICOLA Y DE FZA. ELECTRICA DEL RIO CONCHOS', 162.316, 290.15, 1649, 5, 8.237, '[-105.77453,27.46027,-105.37509,27.57937]', -105.55258, 27.52635, '7668031f5e2cc7087b5f8967b883b6ea',
